/* Notes remain local. Anchors use text hashes + exact offsets; stale anchors are not guessed. */
(()=>{
const $=s=>document.querySelector(s),KEY='gt-notes-v1';let notes=[];try{const n=JSON.parse(localStorage.getItem(KEY)||'[]');if(Array.isArray(n))notes=n.filter(valid)}catch{}let selection=null,undo=null;const blocks=new Map();
function valid(n){return n&&typeof n.id==='string'&&typeof n.key==='string'&&typeof n.quote==='string'&&n.quote.length<=3000&&Number.isInteger(n.start)&&Number.isInteger(n.end)&&n.start>=0&&n.end>n.start&&['gold','teal','rose','line'].includes(n.color)&&typeof n.comment==='string'&&n.comment.length<=4000}
function hash(s){let h=2166136261;for(let i=0;i<s.length;i++)h=Math.imul(h^s.charCodeAt(i),16777619);return(h>>>0).toString(36)}
function index(){blocks.clear();const seen=new Map();document.querySelectorAll('main p,main dd,main td,main li').forEach(p=>{if(p.closest('#memory,#sources,.live-map')||p.classList.contains('ref')||p.classList.contains('map-caption'))return;let text=p.textContent;if(text.length<15)return;const section=p.closest('section')?.id||'main';const base=section+'-'+hash(text);const count=seen.get(base)||0;seen.set(base,count+1);const key=base+'-'+count;p.dataset.noteKey=key;blocks.set(key,p)});draw()}
function save(){try{localStorage.setItem(KEY,JSON.stringify(notes));return true}catch{window.gtToast('浏览器未能保存，请导出笔记备份；当前笔记仍保留在本页。');return false}}
function rangeAt(block,start,end){const walker=document.createTreeWalker(block,NodeFilter.SHOW_TEXT);let total=0,a=null,b=null,ao=0,bo=0;while(walker.nextNode()){let n=walker.currentNode,len=n.textContent.length;if(!a&&start<total+len){a=n;ao=start-total}if(end<=total+len){b=n;bo=end-total;break}total+=len}if(!a||!b)return null;const r=new Range();r.setStart(a,ao);r.setEnd(b,bo);return r}
function anchored(n){const b=blocks.get(n.key);return b&&b.textContent.slice(n.start,n.end)===n.quote?b:null}
function draw(){const supported=!!(window.CSS&&CSS.highlights&&window.Highlight);const ranges={gold:[],teal:[],rose:[],line:[]};blocks.forEach(b=>b.classList.remove('note-fallback'));notes.forEach(n=>{const b=anchored(n);if(!b)return;const r=rangeAt(b,n.start,n.end);if(r){ranges[n.color].push(r);if(!supported)b.classList.add('note-fallback')}});if(supported)Object.keys(ranges).forEach(c=>CSS.highlights.set('gt-'+c,new Highlight(...ranges[c])));renderList()}
function renderList(){const list=$('#notesList');list.replaceChildren();$('#notesCount').textContent=notes.length+' 条';if(!notes.length){let p=document.createElement('p');p.className='muted';p.textContent='选择正文中的一段文字，再点击标记颜色。手机可长按选择文字。';list.append(p)}notes.slice().reverse().forEach(n=>{const item=document.createElement('article');item.className='saved-note note-'+n.color;const jump=document.createElement('button');jump.className='note-quote';jump.textContent=n.quote;jump.title='跳转到原文';jump.onclick=()=>{if(n.city)document.dispatchEvent(new CustomEvent('gt:city',{detail:n.city}));const b=anchored(n);if(!b){window.gtToast('正文已变化，无法准确定位；原摘录仍在笔记中。');return}let d=b.closest('details');while(d){d.open=true;d=d.parentElement.closest('details')}b.scrollIntoView({behavior:document.body.classList.contains('motion-off')?'instant':'smooth',block:'center'});b.classList.add('scroll-flash');setTimeout(()=>b.classList.remove('scroll-flash'),1500);$('#notebook').hidden=true};item.append(jump);const comment=document.createElement('p');comment.textContent=n.comment||'未附加心得';item.append(comment);const meta=document.createElement('small');meta.textContent=(n.section||'研读笔记')+(anchored(n)?'':' · 原文位置待核对');item.append(meta);const edit=document.createElement('button');edit.className='note-mini';edit.textContent='编辑';edit.onclick=()=>{const field=document.createElement('textarea');field.maxLength=4000;field.value=n.comment;const submit=document.createElement('button');submit.textContent='保存';submit.onclick=()=>{n.comment=field.value;save();renderList()};item.replaceChildren(jump,field,submit)};const del=document.createElement('button');del.className='note-mini';del.textContent='移除';del.onclick=()=>{undo=n;notes=notes.filter(x=>x.id!==n.id);save();draw();$('#undoNote').hidden=false;window.gtToast('标记已移除，可在笔记面板撤销。')};item.append(edit,del);list.append(item)})}
function capture(){const sel=getSelection();if(!sel||sel.isCollapsed||!sel.rangeCount)return;const r=sel.getRangeAt(0),el=r.commonAncestorContainer.nodeType===1?r.commonAncestorContainer:r.commonAncestorContainer.parentElement;const block=el.closest?.('[data-note-key]');if(!block||!block.contains(r.startContainer)||!block.contains(r.endContainer)){selection=null;$('#selectionStatus').textContent='请在同一个正文段落中选择文字。';return}const pre=new Range();pre.selectNodeContents(block);pre.setEnd(r.startContainer,r.startOffset);const start=pre.toString().length,quote=r.toString();if(!quote.trim()||quote.length>3000)return;selection={city:block.closest('#placeStory')?.dataset.city||null,key:block.dataset.noteKey,start,end:start+quote.length,quote,section:block.closest('section')?.querySelector('h2')?.textContent||'研读笔记'};$('#selectionStatus').textContent='已选：'+quote.slice(0,90)+(quote.length>90?'…':'');$('#selectionTools').hidden=false}
document.addEventListener('selectionchange',()=>{clearTimeout(capture.timer);capture.timer=setTimeout(capture,100)});
function add(color){if(!selection){window.gtToast('请先在正文中选择一段文字。');return}if(notes.length>=2000){window.gtToast('本机笔记已达2000条，请先导出整理。');return}if(notes.some(n=>n.key===selection.key&&n.start===selection.start&&n.end===selection.end&&n.color===color)){window.gtToast('这一段已有同色标记，可在笔记面板编辑。');return}notes.push({...selection,id:crypto.randomUUID?crypto.randomUUID():Date.now()+'-'+Math.random().toString(36).slice(2),color,comment:$('#noteComment').value.slice(0,4000),createdAt:new Date().toISOString()});save();draw();$('#noteComment').value='';$('#selectionTools').hidden=true;selection=null;getSelection()?.removeAllRanges();window.gtToast('标记已保存到本设备。')}
document.querySelectorAll('[data-note-color]').forEach(b=>{b.addEventListener('pointerdown',e=>e.preventDefault());b.onclick=()=>add(b.dataset.noteColor)});$('#openNotes').onclick=()=>{$('#notebook').hidden=!$('#notebook').hidden;if(!$('#notebook').hidden)renderList()};$('#selectionNote').addEventListener('pointerdown',e=>e.preventDefault());$('#selectionNote').onclick=()=>{$('#notebook').hidden=false;$('#noteComment').focus()};$('#selectionClose').onclick=()=>$('#selectionTools').hidden=true;$('#closeNotes').onclick=()=>$('#notebook').hidden=true;$('#undoNote').onclick=()=>{if(undo){notes.push(undo);undo=null;save();draw();$('#undoNote').hidden=true;window.gtToast('已恢复上一条标记。')}};
$('#exportNotes').onclick=()=>{const b=new Blob([JSON.stringify({format:'GTstudy-notes',version:1,exportedAt:new Date().toISOString(),notes},null,2)],{type:'application/json'}),u=URL.createObjectURL(b),a=document.createElement('a');a.href=u;a.download='GTstudy-notes-'+new Intl.DateTimeFormat('sv-SE',{timeZone:'Asia/Taipei'}).format(new Date())+'.json';a.click();setTimeout(()=>URL.revokeObjectURL(u),1000)};
$('#importNotes').onchange=async e=>{const f=e.target.files[0];if(!f)return;if(f.size>5e6){window.gtToast('笔记文件过大，请选择5MB以内的备份。');return}try{const data=JSON.parse(await f.text());if(data.format!=='GTstudy-notes'||!Array.isArray(data.notes))throw Error();const incoming=data.notes.filter(valid);let added=0;for(const n of incoming){if(notes.length>=2000)break;if(!notes.some(x=>x.id===n.id)){notes.push(n);added++}}save();draw();window.gtToast('已合并导入 '+added+' 条笔记。')}catch{window.gtToast('无法读取该备份，请使用GTstudy导出的JSON笔记。')}e.target.value=''};
document.addEventListener('gt:atlas',index);document.addEventListener('gt:ready',index);document.addEventListener('gt:marked',index);if(document.querySelector('.question'))index();document.addEventListener('keydown',e=>{if(e.key==='Escape'){$('#notebook').hidden=true;$('#selectionTools').hidden=true}});
})();
